// Effect database: names and parameters of all algorithms (data/algorithms.json, generated by
// tools/gen_web_algdb.py in the ampero repo from the Hotone editor's databases).
//
//   await loadAlgDb();            // once; the lookups return null / fall back until it is loaded
//   algInfo(code)                 // {code, name, module, category, params: [...]} or null
//   algParam(code, id)            // one parameter (Widget.ID = index into the 25 floats per slot in tag 5)
//   formatValue(param, value)     // "500 ms", "Off", "Raw", "On" …
//   algsOfCategory(category)      // algorithms of a category (tag 4 mod[] / Catalog index), sorted by name

let db = null;
let loading = null;

/** Load the database (cached). Resolves to true when available, false if it could not be loaded. */
export function loadAlgDb(url = new URL('../data/algorithms.json', import.meta.url)) {
  loading ??= (async () => {
    try {
      const r = await fetch(url);
      if (!r.ok) throw new Error(`${r.status}`);
      db = await r.json();
      return true;
    } catch (e) {
      console.warn('effect database not loaded:', e);
      loading = null; // allow a retry
      return false;
    }
  })();
  return loading;
}

/** For tests / other environments: use an already parsed database. */
export function setAlgDb(data) {
  db = data;
  loading = Promise.resolve(true);
}

export const algDbLoaded = () => !!db;

export const categoryName = (i) => db?.categories[i] ?? null;
export const categoryNames = () => db?.categories ?? null;

export function algInfo(code) {
  const a = db?.algs[String(code >>> 0)];
  if (!a) return null;
  return { code: code >>> 0, name: a.n, module: a.m, category: a.c, params: a.p.map(paramInfo) };
}

function paramInfo(p) {
  return {
    id: p.i, name: p.n, type: p.t, min: p.min, max: p.max, step: p.s, def: p.d,
    options: p.o ?? null, unit: p.u ?? '', offAtMin: !!p.off, limitAtMax: !!p.lim, sync: !!p.sync, knob: p.k ?? null,
  };
}

export function algParam(code, id) {
  return algInfo(code)?.params.find((p) => p.id === id) ?? null;
}

/** Algorithms of one category, sorted by name: [{code, name}]. */
export function algsOfCategory(category) {
  if (!db) return [];
  return Object.entries(db.algs).filter(([, a]) => a.c === category)
    .map(([c, a]) => ({ code: +c, name: a.n })).sort((x, y) => x.name.localeCompare(y.name));
}

const decimals = (step) => {
  const s = String(step);
  return s.includes('.') ? s.length - s.indexOf('.') - 1 : 0;
};

/** Display text of a parameter value (the value as stored in the preset / sent with 0x01040003). */
export function formatValue(p, v) {
  if (!p || typeof v !== 'number' || Number.isNaN(v)) return String(v);
  if (p.options) return p.options[Math.round(v - p.min)] ?? String(v);
  if (p.offAtMin && v <= p.min) return 'Off';
  if (p.limitAtMax && v >= p.max) return 'Limit';
  const n = v.toFixed(decimals(p.step));
  return p.unit === ':1' ? `${n}:1` : p.unit ? `${n} ${p.unit}` : n;
}

/** Clamp and round a value to the parameter's range and step. */
export function clampValue(p, v) {
  const x = Math.min(p.max, Math.max(p.min, v));
  const r = Math.round((x - p.min) / p.step) * p.step + p.min;
  return +r.toFixed(decimals(p.step));
}
